insert into tax_templates
  (country, code, name, name_i18n, description, amount_type, amount, applies_to, treatment,
   valid_from, valid_to, legal_reference, vat_category, exemption_code, sequence,
   tax_kind, recoverable, conditions, jurisdiction, price_include, cash_basis,
   cash_basis_transition_account_code, source_key,
   applies_seller_territory, applies_buyer_territory, applies_supply_territory,
   applies_supply_vs_seller)
values
  ('CG', 'CG-P-189', 'Achats de biens, taux normal 18,9 %', '{}'::jsonb, 'Taxe récupérable sur achats de marchandises, un seul montant à 18,9 %, sans distinguer la part principale de la part des centimes additionnels : le plan SYSCOHADA n''a pas de compte récupérable séparé pour cette distinction, et la directive CEMAC (art. 22-1) n''exige que la déductibilité, pas la traçabilité de la provenance.', 'percent', 18.9, 'purchase', 'domestic', date '1997-01-01', null, 'Loi n° 12-97 du 12 mai 1997, art. 17 et art. 37 ; loi de finances pour 2026, § 4.a et § 4.d, pour le taux facturé de 18,9 % ; directive CEMAC n° 11/22, art. 22-1 — la surtaxe additionnelle n''est admise que si elle est déductible comme la taxe elle-même. PwC (secondaire) la dit non déductible : contradiction non tranchée faute de texte consolidé lu, voir packs/cg/README.md.', 'S', null, 110, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'loi-tva-1997', null, null, null, null),
  ('CG', 'CG-P-189-IMMO', 'Immobilisations, taux normal 18,9 %', '{}'::jsonb, null, 'percent', 18.9, 'purchase', 'domestic', date '1997-01-01', null, 'Loi n° 12-97 du 12 mai 1997, art. 17 et art. 37 ; loi de finances pour 2026, § 4.a et § 4.d ; directive CEMAC n° 11/22, art. 22-1, comme CG-P-189.', 'S', null, 130, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'loi-tva-1997', null, null, null, null),
  ('CG', 'CG-P-189-SRV', 'Services extérieurs, taux normal 18,9 %', '{}'::jsonb, null, 'percent', 18.9, 'purchase', 'domestic', date '1997-01-01', null, 'Loi n° 12-97 du 12 mai 1997, art. 17 et art. 37 ; loi de finances pour 2026, § 4.a et § 4.d ; directive CEMAC n° 11/22, art. 22-1, comme CG-P-189.', 'S', null, 120, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'loi-tva-1997', null, null, null, null),
  ('CG', 'CG-P-5', 'Achats de biens de l''annexe 5, taux réduit 5 %', '{}'::jsonb, null, 'percent', 5, 'purchase', 'domestic', date '2026-01-01', null, 'Loi n° 12-97 du 12 mai 1997, annexe 5, liste remplacée par la loi de finances pour 2026, § 18.3.', 'S', null, 140, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'lf-2026', null, null, null, null),
  ('CG', 'CG-S-189', 'Ventes de biens, taux normal 18 % + centimes additionnels 5 % (18,9 % cumulé)', '{}'::jsonb, 'Livraisons de biens au taux normal de 18 %, majoré des centimes additionnels de 5 % de la TVA (0,9 point de base) : le compte 4431 reçoit la part principale de la taxe (20/21e, soit 95,238 % de la taxe facturée) et le compte 446 la part des centimes additionnels (1/21e, soit 4,762 %). Un seul taux de 18,9 % appliqué une fois, jamais 18 % puis 5 % du résultat pris séparément : deux arrondis successifs peuvent s''écarter d''une unité monétaire de l''arrondi unique que porte la facture.', 'percent', 18.9, 'sale', 'domestic', date '1997-01-01', null, 'Loi n° 12-97 du 12 mai 1997, art. 17 (texte d''origine) — taux normal de 18 % ; art. 37 — centimes additionnels maintenus au taux de 5 % de la TVA, issus de la taxe complémentaire sur le chiffre d''affaires (TCA) de 1994 ; loi de finances pour 2026 (loi n° 42-2025), § 4.a et § 4.d — confirme les « centimes additionnels à la TVA, fixés à 5 % du montant de la TVA » et un « précompte... au taux cumulé de 18,9 % ». Le texte en vigueur (numérotation actuelle des articles) n''a pas été trouvé : le taux et les centimes sont ceux que la loi de finances pour 2026 confirme en vigueur. Compte 446 « État, autres taxes sur le chiffre d''affaires » retenu plutôt que 4422 « Impôts et taxes pour les collectivités publiques » (choisi par packs/td/ et packs/cm/ pour leur propre surtaxe) parce qu''aucune source lue n''établit que les centimes additionnels congolais reviennent aux collectivités locales — la loi de finances pour 2026 les rattache au budget de l''État (précompte versé au Trésor Public), sans texte trouvé qui les dise communaux ; c''est un choix documenté, pas le seul défendable. Déductibilité à l''achat : directive CEMAC n° 11/22, art. 22-1 — une surtaxe additionnelle à la TVA n''est admise que si elle est déductible dans les mêmes conditions que la taxe elle-même ; PwC (source secondaire, revue le 07/08/2026) la dit pourtant non déductible, ce que ce pack ne peut ni confirmer ni exclure faute de texte consolidé lu — voir packs/cg/README.md.', 'S', null, 10, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'loi-tva-1997', null, null, null, null),
  ('CG', 'CG-S-189-SRV', 'Prestations de services, taux normal 18 % + centimes additionnels 5 % (18,9 % cumulé)', '{}'::jsonb, 'Prestations de services, même taux affiché et même répartition que CG-S-189, taxe portée au compte 4432 pour sa part principale.', 'percent', 18.9, 'sale', 'domestic', date '1997-01-01', null, 'Loi n° 12-97 du 12 mai 1997, art. 17 et art. 37 ; loi de finances pour 2026, § 4.a et § 4.d, comme CG-S-189.', 'S', null, 20, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'loi-tva-1997', null, null, null, null),
  ('CG', 'CG-S-5', 'Biens de l''annexe 5, taux réduit 5 %', '{}'::jsonb, 'Biens de consommation courante de l''annexe 5 de la loi TVA : laits, tomate, riz, farine de froment, sucre, boulangerie et biscuiterie, sel. Aucun centime additionnel n''est porté sur ce taux : la loi de finances pour 2026 ne dit ni ne l''exclut, et ce pack ne tranche pas ce qu''aucune disposition trouvée ne tranche.', 'percent', 5, 'sale', 'domestic', date '2026-01-01', null, 'Loi n° 12-97 du 12 mai 1997, annexe 5, liste remplacée par la loi de finances pour 2026 (loi n° 42-2025), § 18.3. Le taux réduit existait déjà en 2012 (loi n° 8-2012) ; la liste actuellement en vigueur est celle de la loi de finances pour 2026, au 1er janvier 2026.', 'S', null, 30, 'vat', true, array['supply_nature']::tax_condition[], null, false, false, null, 'lf-2026', null, null, null, null),
  ('CG', 'CG-S-EXO', 'Opération exonérée (annexe 3)', '{}'::jsonb, 'Viandes et volailles ; poissons de mer (hors luxe) et poisson salé ; blé et maïs non de semence ; huile végétale ; aliments pour enfants ; levure ; aliments du bétail ; sel ; quinine, insuline, antibiotiques, produits pharmaceutiques ; engrais ; insecticides ; articles d''hygiène médicale ; cahiers, livres scolaires et autres livres ; lunettes ; fauteuils roulants ; appareils et mobilier médicaux.', 'percent', 0, 'sale', 'exempt', date '2026-01-01', null, 'Loi n° 12-97 du 12 mai 1997, annexe 3, liste remplacée par la loi de finances pour 2026 (loi n° 42-2025), § 18.3, vérifiée sur le fac-similé du Journal officiel.', 'E', null, 50, 'vat', true, array['supply_nature']::tax_condition[], null, false, false, null, 'lf-2026', null, null, null, null),
  ('CG', 'CG-S-EXP', 'Exportation, taux zéro', '{}'::jsonb, 'Exportations visées par la douane et transports internationaux.', 'percent', 0, 'sale', 'export', date '1997-01-01', null, 'Loi n° 12-97 du 12 mai 1997, art. 17 (texte d''origine) — taux zéro sur les exportations et le transport international. Le texte en vigueur (numérotation actuelle) n''a pas été trouvé.', 'G', null, 40, 'vat', true, array['transport_evidence']::tax_condition[], null, false, false, null, 'loi-tva-1997', null, null, null, null)
on conflict (country, code) do update set
  name            = excluded.name,
  name_i18n       = excluded.name_i18n,
  description     = excluded.description,
  amount_type     = excluded.amount_type,
  amount          = excluded.amount,
  applies_to      = excluded.applies_to,
  treatment       = excluded.treatment,
  valid_from      = excluded.valid_from,
  valid_to        = excluded.valid_to,
  legal_reference = excluded.legal_reference,
  vat_category    = excluded.vat_category,
  exemption_code  = excluded.exemption_code,
  sequence        = excluded.sequence,
  tax_kind        = excluded.tax_kind,
  recoverable     = excluded.recoverable,
  conditions      = excluded.conditions,
  jurisdiction    = excluded.jurisdiction,
  price_include   = excluded.price_include,
  cash_basis      = excluded.cash_basis,
  cash_basis_transition_account_code = excluded.cash_basis_transition_account_code,
  source_key      = excluded.source_key,
  applies_seller_territory = excluded.applies_seller_territory,
  applies_buyer_territory  = excluded.applies_buyer_territory,
  applies_supply_territory = excluded.applies_supply_territory,
  applies_supply_vs_seller = excluded.applies_supply_vs_seller;

