insert into tax_report_templates
  (country, code, name, periods, period_default, valid_from, valid_to, legal_reference,
   is_periodic_return, deadline_rule, deadline_day, deadline_plus_days,
   deadline_reference, deadline_source_key, file_format)
values
  ('CG', 'CG-TVA', 'Déclaration de taxe sur la valeur ajoutée', array['month']::declaration_period[], 'month'::declaration_period, date '2026-01-01', null, 'Loi n° 12-97 du 12 mai 1997, art. 32 (texte d''origine) — la déclaration est mensuelle, conforme au modèle prescrit par l''administration ; confirmé par PwC (secondaire, revu le 07/08/2026) et Almathe & Associés (secondaire). Le texte en vigueur (numérotation actuelle) n''a pas été trouvé : le nom du formulaire et la numérotation de ses cases ne sont publiés dans aucune source officielle trouvée. Les cases de ce fichier sont nommées d''après ce que l''art. 17, l''art. 37 et l''annexe 3/5 de la loi TVA font déclarer, non d''après un formulaire, comme au Tchad et au Sénégal. L''échéance elle-même n''est pas portée ici (pas de `deadline`) : le texte d''origine de 1997 dit « dans les quinze jours du mois suivant » (art. 31), PwC dit « before the 20th day of every month » — deux sources en désaccord, aucun texte consolidé lu pour trancher.', true,null, null, null, null, null, null)
on conflict (country, code) do update set
  name                = excluded.name,
  periods             = excluded.periods,
  period_default      = excluded.period_default,
  valid_from          = excluded.valid_from,
  valid_to            = excluded.valid_to,
  legal_reference     = excluded.legal_reference,
  is_periodic_return  = excluded.is_periodic_return,
  deadline_rule       = excluded.deadline_rule,
  deadline_day        = excluded.deadline_day,
  deadline_plus_days  = excluded.deadline_plus_days,
  deadline_reference  = excluded.deadline_reference,
  deadline_source_key = excluded.deadline_source_key,
  file_format         = excluded.file_format;

