values
  ('CG', 'CG-TVA', 'CA189', 'base', 'Opérations taxables au taux normal (18,9 % facturés)', '{}'::jsonb, 10, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Loi n° 12-97 du 12 mai 1997, art. 17 et art. 37', 'loi-tva-1997'),
  ('CG', 'CG-TVA', 'CA5', 'base', 'Opérations taxables au taux réduit de 5 % (annexe 5)', '{}'::jsonb, 20, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Loi n° 12-97 du 12 mai 1997, annexe 5, dans la rédaction de la loi de finances pour 2026, § 18.3', 'lf-2026'),
